  public static void addFlyOver(Questionnaire.QuestionnaireItemComponent item, String text, String linkId){
    if (!StringUtils.isBlank(text)) {
      Questionnaire.QuestionnaireItemComponent display = item.addItem();
      display.setType(Questionnaire.QuestionnaireItemTypeUsable.DISPLAY);
      display.setText(text);
      display.setLinkId(linkId);
      display.getExtensionList().add(Factory.newExtension(ExtensionDefinitions.EXT_CONTROL, Factory.newCodeableConcept("flyover", "http://hl7.org/fhir/questionnaire-item-control", "Fly-over"), true));
    }
  }

