  public static VersionResolutionRules getVersionResolutionRulesBase(Base base) {
    if (base == null) {
      return VersionResolutionRules.defaultRule();
    }
//    if (base instanceof org.hl7.fhir.model.elementmodel.Element) {
//      return getVersionResolutionRules((org.hl7.fhir.model.elementmodel.Element) base);
//    } else
    if (base instanceof Element) {
      return getVersionResolutionRules((Element) base);
    } else {
      return VersionResolutionRules.defaultRule();
    }
  }


